INSERT INTO "CastingCall" ("id","title","company","medium","location","compensation","shootDates","deadline","shootStart","requiresAudition","isPublic","description","requirements","tags","seedApplicants","createdAt","postedById") VALUES ('monsoon-chess-lead','Female lead, 28–38 — indie feature ''Monsoon Chess''','Ashvattha Films','Feature Film','Mumbai','Paid — ₹12L, 42 shoot days','Sep 15 – Nov 8, 2026','2026-07-28T23:59:59Z','2026-09-15T09:00:00Z',true,true,'Dev Malhotra''s second feature. ''Nalini'' is a district-level chess coach in coastal Maharashtra whose estranged daughter returns during the monsoon. The part carries the film — long takes, minimal dialogue, everything in the eyes. Marathi fluency is a genuine advantage; we will workshop for three weeks before camera.',ARRAY['Self-tape: scene 14 (sides provided on shortlist), 2 takes max','Recent headshot + full-length, natural light','3-week workshop attendance in Mumbai (paid)','No concurrent commitments Sep–Nov 2026'],ARRAY['Lead role','Paid','Festival film','Workshop'],148,'2026-07-06T14:15:38.057Z','ritika-nair');
