INSERT INTO "CastingCall" ("id","title","company","medium","location","compensation","shootDates","deadline","shootStart","requiresAudition","isPublic","description","requirements","tags","seedApplicants","createdAt","postedById") VALUES ('crosswind-negative-lead','Negative lead, 35–50 — prime-time series ''Crosswind'' reboot','Sterling Television','TV Series','Mumbai (Film City)','Paid — monthly contract, 22 days/month','On floor from Sep 2026, 9-month arc','2026-07-30T23:59:59Z','2026-09-01T09:00:00Z',true,true,'The beloved aviation drama returns, and it needs a villain the audience loves to hate. A corporate raider circling the family airline. Long-arc television: consistency, stamina, and the ability to make a monologue land at 7am matter more than anything.',ARRAY['Self-tape: provided monologue, one continuous take','Mumbai-based or willing to relocate','9-month exclusivity for the arc'],ARRAY['TV','Paid','Long arc','Lead'],119,'2026-07-05T14:15:38.057Z','lena-fernandes');
