INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-1','ritika-nair','CASTING','Saltwater S3 casting is officially open — four recurring roles, shooting in Goa from August. We''re prioritising Konkani speakers and Goa-based artists for fittings. Full brief and self-tape instructions on the call. Please, PLEASE slate your height.','2026-07-09T13:15:38.057Z',NULL,NULL,NULL,NULL,NULL,'saltwater-s3-supporting',214,38);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-2','dev-malhotra','ANNOUNCEMENT','Some personal news: ''Monsoon Chess'' is fully financed. Ashvattha Films is producing, we shoot in September on the Konkan coast, and casting for Nalini begins this week. It took three years and eleven drafts. To everyone who read one of them — thank you.','2026-07-09T11:15:38.057Z','Monsoon Chess — first lookbook frame','IN DEVELOPMENT','2026','PORCELAIN','WIDE',NULL,892,127);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-3','ishaan-verma','TRAILER','Locked the Saltwater S2 teaser at 4am. Sixty seconds, no dialogue, one wave. Sometimes the cut tells you when it''s done — you just have to be awake to hear it.','2026-07-09T09:15:38.057Z','Saltwater S2 — Teaser','TEASER · 0:60','2026','STEEL','WIDE',NULL,356,44);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-4','aanya-sharma','BTS','Day 40 of 42 on ''Half Light''. Kabir lit this entire scene with one practical bulb and a bounce board, and it''s the best I''ve ever looked on camera. Hire cinematographers who treat light like dialogue.','2026-07-09T05:15:38.057Z','Half Light — Day 40','BTS','2025','MIDNIGHT','WIDE',NULL,641,72);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-5','sana-iyer','CASTING','Choreographing the new Peppermint video and we need EIGHT dancers plus an assistant choreographer. Flooded warehouse, ankle-deep water, the most fun brief I''ve had in years. Movement tape details on the call — tag a dancer who isn''t afraid to get wet.','2026-07-09T00:15:38.057Z',NULL,NULL,NULL,NULL,NULL,'peppermint-dancers',178,51);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-6','vikram-sethi','ANNOUNCEMENT','Ashvattha update: ''Half Light'' has been invited to three international festivals we can''t name yet, ''Saltwater'' S3 is greenlit, and ''Monsoon Chess'' shoots in September. Slate of five, two in production. We are reading scripts again from August 1.','2026-07-08T14:15:38.057Z',NULL,NULL,NULL,NULL,NULL,NULL,1043,156);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-7','zoya-qureshi','BTS','Recorded scratch vocals for an animated feature at 2am from my home studio in Hyderabad, and the director approved take two. The 24-hour-turnaround reputation survives another week.','2026-07-08T14:15:38.057Z','Home studio — 2am session','BTS','2026','DUSK','SQUARE',NULL,233,29);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-8','lena-fernandes','ANNOUNCEMENT','Firstline is opening its writer roster for the first time in two years. We rep 12 writers; we have room for 3 more. Features and limited series only. If your sample makes us miss a meeting, you''re in.','2026-07-07T14:15:38.057Z',NULL,NULL,NULL,NULL,NULL,NULL,467,88);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-9','kabir-mehta','TRAILER','''Dhaaga'' crossed 62 million views. Two years since we shot it in one rained-out night in Alibaug. Dev kept saying ''the weather IS the video''. He was right. Full video on the reel.','2026-07-07T14:15:38.057Z','Peppermint — ''Dhaaga''','MUSIC VIDEO','2023','DUSK','WIDE',NULL,1520,203);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-10','rohan-chatterjee','ANNOUNCEMENT','After 200 nights of ''Gulmohar Lane'' I said I''d never do it again. They''re reviving it at Prithvi for the 10th anniversary and recasting the whole ensemble. I might audition for my own old part. Is that allowed? Asking for me.','2026-07-06T14:15:38.057Z',NULL,NULL,NULL,NULL,NULL,'gulmohar-lane-revival',389,95);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-11','priya-venkat','CASTING','The Paper Kite 2 is recording in Hindi AND Tamil simultaneously — bilingual voice artists, this is the gig you''ve been waiting for. Remote sessions accepted via Source-Connect. I dub-directed the Tamil track on part one; this team is a dream.','2026-07-06T14:15:38.057Z',NULL,NULL,NULL,NULL,NULL,'paper-kite-2-voices',156,24);
INSERT INTO "Post" ("id","authorId","kind","text","createdAt","mediaTitle","mediaKind","mediaYear","mediaTone","mediaAspect","castingCallId","seedLikes","seedComments") VALUES ('post-12','nikhil-bhandari','BTS','Recorded a 34-piece string section for the ''Half Light'' finale today. There''s a moment at bar 112 where the room went quiet after the take. That silence is why we do this.','2026-07-05T14:15:38.057Z','Half Light — string session','SCORE · BTS','2025','NOIR','WIDE',NULL,578,61);
