INSERT INTO "Message" ("id","conversationId","senderId","text","createdAt") VALUES ('conv-sana-m2','conv-sana','demo-talent','Cutting my movement tape this weekend. Any notes on what you want to see?','2026-07-06T13:25:38.057Z');
